            "solution": "<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Payment\\State;\n\ninterface PaymentStateInterface\n{\n    public function process(PaymentProcessor $processor): bool;\n    public function getStatus(): string;\n}\n\nclass CreatedState implements PaymentStateInterface\n{\n    public function process(PaymentProcessor $processor): bool\n    {\n        // Validate payment method\n        if (empty($processor->payment['method'])) {\n            return false;\n        }\n        $processor->payment['status'] = 'created';\n        return true;\n    }\n\n    public function getStatus(): string\n    {\n        return 'created';\n    }\n}\n\nclass PendingState implements PaymentStateInterface\n{\n    public function process(PaymentProcessor $processor): bool\n    {\n        $processor->payment['status'] = 'pending';\n        $processor->payment['pending_at'] = date('Y-m-d H:i:s');\n        return true;\n    }\n\n    public function getStatus(): string\n    {\n        return 'pending';\n    }\n}\n\nclass CompletedState implements PaymentStateInterface\n{\n    public function process(PaymentProcessor $processor): bool\n    {\n        $processor->payment['status'] = 'completed';\n        $processor->payment['completed_at'] = date('Y-m-d H:i:s');\n        return true;\n    }\n\n    public function getStatus(): string\n    {\n        return 'completed';\n    }\n}\n\nclass FailedState implements PaymentStateInterface\n{\n    public function process(PaymentProcessor $processor): bool\n    {\n        $processor->payment['status'] = 'failed';\n        $processor->payment['failed_at'] = date('Y-m-d H:i:s');\n        return false;\n    }\n\n    public function getStatus(): string\n    {\n        return 'failed';\n    }\n}\n\nclass RefundedState implements PaymentStateInterface\n{\n    public function process(PaymentProcessor $processor): bool\n    {\n        $processor->payment['status'] = 'refunded';\n        $processor->payment['refunded_at'] = date('Y-m-d H:i:s');\n        return true;\n    }\n\n    public function getStatus(): string\n    {\n        return 'refunded';\n    }\n}\n\nclass PaymentProcessor\n{\n    public array $payment;\n    private PaymentStateInterface $state;\n\n    public function setState(PaymentStateInterface $state): void\n    {\n        $this->state = $state;\n    }\n\n    public 